import{z as i,x as A,o as t,c as l,q as E,j as n,D as c,d as a,s as d,S as r,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"条件码与谓词执行","description":"","frontmatter":{"title":"条件码与谓词执行","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/condition-codes-predication.md","filePath":"cs/condition-codes-predication.md","lastUpdated":1791063341000}'),B={name:"cs/condition-codes-predication.md"};function C(p,e,m,R,h,S){const s=A("Mermaid");return t(),l("div",null,[e[2]||(e[2]=E('<h1 id="条件码与谓词执行" tabindex="-1">条件码与谓词执行 <a class="header-anchor" href="#条件码与谓词执行" aria-label="Permalink to &quot;条件码与谓词执行&quot;">​</a></h1><div class="epigraph"><p>比较的结果可以藏进 NZCV / EFLAGS，也可以写成 GPR 里的 0/1；谓词把短分支收成选路，避免前端为一条 `if` 付冲刷。</p><footer>—— 据 ARM Architecture Reference Manual；Intel SDM；The RISC-V Instruction Set Manual；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/bit-manip-ext">上一课</a>的 <code>min</code>/<code>clz</code> 写出的是寄存器值。<a href="/cs/aarch64-isa">AArch64</a> 已点名 NZCV，<a href="/cs/arm-vs-riscv">ARM 对 RISC-V</a> 把「条件码 vs 比较进寄存器」留到本课。缺口是 <strong>标志位与谓词</strong>：谁写、谁读、如何消掉短分支。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>x86：多数整数运算更新 EFLAGS（ZF/SF/OF/CF）；<code>jcc</code> 与 <code>cmov</code> 读它们。ARM：可选 <code>S</code> 后缀写 NZCV，<code>b.cond</code> / <code>csel</code> 消费。RISC-V：无条件码，<code>blt</code> 直接比较两个 GPR，<code>slt</code> 把布尔写进寄存器。<span class="marginnote">「NZCV」翻译成白话：N=结果为负、Z=结果为零、C=进位或借位、V=有符号溢出——四根一位的小旗。比较指令一跑就插旗，后面的条件分支只看旗、不再看操作数；代价是每条运算指令都多了一个看不见的「写口」。</span>缺口不是再介绍分支指令，而是<strong>隐式标志堆 vs 显式比较</strong>对流水线与编译器的后果。</p><p>谓词：用布尔选结果而不跳转。部分谓词是 <code>cmov</code>/<code>csel</code>；A32 曾给多数指令条件域；Itanium 把谓词寄存器做成常规。 <a href="/cs/rvv-vector">RVV</a> 的掩码是向量谓词，本课对照标量。</p><h3 id="谓词不是「取消分支预测」" tabindex="-1">谓词不是「取消分支预测」 <a class="header-anchor" href="#谓词不是「取消分支预测」" aria-label="Permalink to &quot;谓词不是「取消分支预测」&quot;">​</a></h3><p>长偏置分支仍该跳。谓词消灭的是<strong>短、难预测</strong>的 <code>if</code>，并可能拉长数据依赖、多执行两边。<span class="marginnote">初学者容易以为谓词执行是「更聪明的分支预测」，实际上它根本绕开了预测：两条路径都算出来，再用一个布尔值挑答案。好处是永远不会预测错、没有冲刷；坏处是白算了注定不要的那条路——所以只适合两边都便宜的短 <code>if</code>。</span>把 NZCV 当预测器状态，下一课 <a href="/cs/gshare-predictor">gshare</a> 会对不上：预测器看的是分支历史，不是条件码 CSR。</p><p><span class="marginnote">ARM ARM 的 PSTATE 与 CSEL。Intel SDM 的 Jcc/CMOV 与 EFLAGS。RISC-V 无标志是刻意选择。CA:AQA 讨论谓词与条件移动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器：若 ISA 有 <code>csel</code> 且两边都便宜，发条件选；否则发比较+分支，把方向交给前端。<span class="marginnote">给个数字实例：一条 if 走对分支约 1 个周期，走错要冲刷前端约 15 个周期；方向五五开时平均成本约 \\(\\frac{1+15}{2}=8\\) 周期，而 <code>csel</code>/<code>cmov</code> 恒定 1–2 周期。分支越不可预测，谓词越赚；反之偏置 99% 的分支就该老老实实跳。</span>RISC-V 用 <code>slt</code>+掩码或分支；B 扩展的 <code>min</code> 是谓词的代数特例。x86 部分标志改写曾造成 stall，微结构用合并与重命名缓解——那是后课乱序，本课只要求「标志是额外的写口」。</p>',11)),(t(),n(r,null,{default:c(()=>[d(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CMP%5B%22%E6%AF%94%E8%BE%83%22%5D%20--%3E%20CC%5B%22%E5%86%99%20NZCV%20%2F%20EFLAGS%22%5D%0A%20%20CMP%20--%3E%20GPR%5B%22slt%20%E5%86%99%20GPR%22%5D%0A%20%20CC%20--%3E%20BR%5B%22%E6%9D%A1%E4%BB%B6%E5%88%86%E6%94%AF%22%5D%0A%20%20CC%20--%3E%20SEL%5B%22csel%20%2F%20cmov%22%5D%0A%20%20GPR%20--%3E%20BR%0A%20%20SEL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%A4%9A%E5%AD%97%E8%8A%82%E5%9C%A8%E5%86%85%E5%AD%98%E9%87%8C%E7%9A%84%E6%AC%A1%E5%BA%8F%22%5D%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("p",null,[a("与 "),o("a",{href:"/cs/fence-instructions"},"fence"),a("：条件码是核内控制状态，不参与多核内存序。")],-1)),e[4]||(e[4]=o("h2",{id:"机制",tabindex:"-1"},[a("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=o("p",null,[a("ISA 对照到这里，控制流接口已经分叉：ARM/x86 的隐式 CC 让一条 "),o("code",null,"sub"),a(" 同时服务算术与后续 "),o("code",null,"b.eq"),a("；RISC-V 把布尔留在 GPR，译码与重命名少一个标志堆。")],-1)),(t(),n(r,null,{default:c(()=>[d(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IF%5B%22%E5%90%8C%E4%B8%80%E5%8F%A5%20if%EF%BC%9A%E6%8C%89%20x%20%E4%B8%8E%20y%20%E7%9A%84%E5%A4%A7%E5%B0%8F%E9%80%89%20a%20%E6%88%96%20b%22%5D%20--%3E%20X86%5B%22x86%EF%BC%9Acmp%20%E5%86%99%20EFLAGS%EF%BC%8Ccmov%20%E8%AF%BB%22%5D%0A%20%20IF%20--%3E%20ARM%5B%22ARM%EF%BC%9Asubs%20%E5%86%99%20NZCV%EF%BC%8Ccsel%20%E8%AF%BB%22%5D%0A%20%20IF%20--%3E%20RV%5B%22RISC-V%EF%BC%9Aslt%20%E6%8A%8A%E5%B8%83%E5%B0%94%E5%86%99%20GPR%EF%BC%8C%E5%86%8D%E6%8C%89%E4%BD%8D%E9%80%89%22%5D%0A%20%20X86%20--%3E%20NOBR%5B%22%E5%85%A8%E7%A8%8B%E6%97%A0%E5%88%86%E6%94%AF%EF%BC%9A%E9%A2%84%E6%B5%8B%E5%99%A8%E4%B8%8D%E5%8F%82%E4%B8%8E%EF%BC%8C%E6%97%A0%E5%86%B2%E5%88%B7%22%5D%0A%20%20ARM%20--%3E%20NOBR%0A%20%20RV%20--%3E%20NOBR%0A%20%20NOBR%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E4%B8%A4%E6%9D%A1%E8%B7%AF%E5%BE%84%E9%83%BD%E6%89%A7%E8%A1%8C%EF%BC%8C%E6%95%B0%E6%8D%AE%E4%BE%9D%E8%B5%96%E5%8F%98%E9%95%BF%22%5D%0A"})]),fallback:c(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=E('<p>下一课大小端处理的是<strong>数据在内存中的字节序</strong>，与「比较结果放哪」正交，但 ABI 会同时规定两者。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Itanium 编译器全集，不把 GPU 的 divergence 当标量谓词。不列全部 <code>jcc</code> 助记符。不进入数据库 SQL 谓词下推。</p><p>后课默认：x86/ARM 用条件码；RISC-V 比较进寄存器或直接分支；<code>cmov</code>/<code>csel</code> 是部分谓词。下一课大小端。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条件码是隐式布尔；RISC-V 选择显式 GPR。</li><li>谓词用选路换短分支，不取消预测器。</li><li>向量掩码已在 RVV，本课钉标量。</li><li>出处：ARM ARM；Intel SDM；RISC-V ISA；Hennessy and Patterson, CA:AQA。</li></ul>',6))])}const u=i(B,[["render",C]]);export{f as __pageData,u as default};
